/**
 * NexHealth public packet embed widget.
 * Usage:
 * <script data-label="Forms" type="text/javascript"
 *   src="https://yoursite.com/static/js/public_packet.min.js"
 *   data-packet-url="https://yoursite.com/p/abc123"></script>
 */
(function () {
  var script = document.currentScript;
  if (!script) {
    var scripts = document.getElementsByTagName("script");
    script = scripts[scripts.length - 1];
  }
  if (!script) return;

  var url = script.getAttribute("data-packet-url");
  var label = script.getAttribute("data-label") || "Forms";
  if (!url) return;

  var wrap = document.createElement("div");
  wrap.setAttribute("data-nex-packet-widget", "true");
  wrap.style.display = "inline-block";

  var btn = document.createElement("a");
  btn.href = url;
  btn.target = "_blank";
  btn.rel = "noopener noreferrer";
  btn.textContent = label;
  btn.style.cssText =
    "display:inline-block;padding:10px 20px;background:#2563eb;color:#ffffff;" +
    "font-family:system-ui,-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif;" +
    "font-size:14px;font-weight:600;line-height:1.25;border-radius:8px;text-decoration:none;" +
    "box-shadow:0 1px 2px rgba(0,0,0,0.08);transition:background 0.15s ease;";

  btn.addEventListener("mouseenter", function () {
    btn.style.background = "#1d4ed8";
  });
  btn.addEventListener("mouseleave", function () {
    btn.style.background = "#2563eb";
  });

  wrap.appendChild(btn);
  if (script.parentNode) {
    script.parentNode.insertBefore(wrap, script.nextSibling);
  }
})();
